CREATE OR REPLACE FUNCTION public.funktion_jira_ticket_lesen(p_ticket_key text, p_audiences text[])
 RETURNS TABLE(ticket_key text, summary text, status text, resolution text, priority text, issue_type text, assignee_name text, jira_updated_at timestamp with time zone, description text, audience text)
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE
  v_allowed constant text[] := ARRAY['public','it_internal'];
BEGIN
  IF p_audiences IS NULL OR array_length(p_audiences,1) IS NULL THEN
    RAISE EXCEPTION 'funktion_jira_ticket_lesen: p_audiences ist Pflicht';
  END IF;
  IF EXISTS (SELECT 1 FROM unnest(p_audiences) a WHERE a <> ALL (v_allowed)) THEN
    RAISE EXCEPTION 'funktion_jira_ticket_lesen: unzulaessiger audience-Wert';
  END IF;
  IF p_ticket_key IS NULL OR btrim(p_ticket_key) = '' THEN
    RAISE EXCEPTION 'funktion_jira_ticket_lesen: p_ticket_key ist Pflicht';
  END IF;

  RETURN QUERY
  SELECT t.ticket_key, t.summary, t.status, t.resolution, t.priority,
         t.issue_type, t.assignee_name, t.jira_updated_at,
         left(COALESCE(t.description,''), 1500),
         t.audience
  FROM public.jira_tickets t
  WHERE upper(t.ticket_key) = upper(btrim(p_ticket_key))
    AND t.audience = ANY (p_audiences)
  LIMIT 1;
END;
$function$
